const output = [];

for (const item of items) {

  // Skip empty Airtable records
    if (!item.json.id && !item.json.fields) {
        continue;
    }

    const recordId = item.json.id || null;
    const fields = item.json.fields || {};

    output.push({
        json: {
            duplicate: Boolean(recordId),


document_airtable_record_id: [recordId],

            next_action: recordId
                ? "duplicate_handler"
                : "continue",

            document_record_id: recordId,
            document_uuid: fields["Document UUID Created in n8n"] || null,
            document_id: fields["Document ID"] || null,
            hash: fields["Document Hash"] || null,
        }
    });

}

return output;

// ===============================================
// Enterprise Knowledge Management Platform
// Workflow 2 - Determine Extraction Method
// ===============================================

const output = [];

for (const item of items) {

    const extension = (item.json.file_extension || "").toLowerCase();

    let extractionMethod = "";
    let parserType = "";
    let supported = true;

    switch (extension) {

        case "txt":
            extractionMethod = "Plain Text";
            parserType = "text";
            break;

        case "pdf":
            extractionMethod = "PDF Parser";
            parserType = "pdf";
            break;

        case "docx":
            extractionMethod = "DOCX Parser";
            parserType = "docx";
            break;

        default:
            extractionMethod = "Unsupported";
            parserType = "unsupported";
            supported = false;
            break;
    }

    output.push({
        json: {
            ...item.json,

            extraction_method: extractionMethod,
            parser_type: parserType,
            supported_file: supported
        },

        binary: item.binary
    });

}

return output;

// ===============================================
// Enterprise Knowledge Management Platform
// Workflow 2 - Normalize Text & Calculate Statistics
// ===============================================

const output = [];

for (const item of items) {

    // -----------------------------
    // Get extracted text
    // -----------------------------
    const rawText = item.json.text || "";

    // -----------------------------
    // Normalize text
    // -----------------------------
    const normalizedText = rawText
        .replace(/\r\n/g, "\n")        // Windows -> Unix line endings
        .replace(/\r/g, "\n")          // Old Mac -> Unix
        .replace(/\t/g, " ")           // Tabs -> Spaces
        .replace(/[ ]+/g, " ")         // Multiple spaces -> Single
        .replace(/\n{3,}/g, "\n\n")    // Max two consecutive blank lines
        .trim();

    // -----------------------------
    // Statistics
    // -----------------------------
    const characterCount = normalizedText.length;

    const wordCount = normalizedText.length === 0
        ? 0
        : normalizedText.split(/\s+/).length;

    const lineCount = normalizedText.length === 0
        ? 0
        : normalizedText.split("\n").length;

    // -----------------------------
    // Build output
    // -----------------------------
    output.push({

        json: {

            ...item.json,

            normalized_text: normalizedText,

            text_length: characterCount,

            word_count: wordCount,

            line_count: lineCount

        },

        binary: item.binary

    });

}

return output;

// =======================================================
// Enterprise Knowledge Platform
// Intelligent Section Aware Chunker
// Version 3.0
// PART 1
// =======================================================


// ---------------- CONFIGURATION ----------------

const CONFIG = {

    CHUNK_SIZE: 1000,

    OVERLAP: 200,

    MIN_CHUNK_SIZE: 100,

    SEARCH_WINDOW: 200,

    MAX_HEADING_LENGTH: 60,

    MAX_HEADING_WORDS: 8

};


// ---------------- UUID ----------------

function generateUUID(){

    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'

    .replace(/[xy]/g,function(c){

        const r=Math.random()*16|0;

        const v=c==='x' ? r : (r&0x3|0x8);

        return v.toString(16);

    });

}


// ---------------- Helpers ----------------

function wordCount(text){

    return text.trim().split(/\s+/).filter(Boolean).length;

}

function isBlank(line){

    return line.trim()==="";

}


// =======================================================
// Heading Detection
// =======================================================


// Markdown

function isMarkdownHeading(line){

    return /^#{1,6}\s+/.test(line);

}


// Number heading

function isNumberHeading(line){

    return /^\d+(\.\d+)*[\.\)]\s+/.test(line);

}


// ALL CAPS

function isAllCapsHeading(line){

    const clean=line.replace(/[^A-Za-z ]/g,"").trim();

    if(clean.length<3) return false;

    return clean===clean.toUpperCase();

}


// Bullet

function isBullet(line){

    return /^\s*[-*•]\s+/.test(line);

}


// Looks like title

function isTitleHeading(line){

    if(!line.trim()) return false;

    if(isBullet(line)) return false;

    if(line.length>CONFIG.MAX_HEADING_LENGTH) return false;

    if(/[.!?]$/.test(line)) return false;

    const words=line.trim().split(/\s+/);

    if(words.length>CONFIG.MAX_HEADING_WORDS) return false;

    let capitalized=0;

    for(const word of words){

        if(/^[A-Z]/.test(word))

            capitalized++;

    }

    return capitalized>=Math.ceil(words.length*0.8);

}


// Context-aware heading detection

function isHeading(lines,index){

    const line=lines[index].trim();

    if(!line) return false;

    if(

        isMarkdownHeading(line)

        ||

        isNumberHeading(line)

        ||

        isAllCapsHeading(line)

    ){

        return true;

    }

    if(!isTitleHeading(line))

        return false;

    const previous=index>0 ? lines[index-1].trim() : "";

    const next=index<lines.length-1 ? lines[index+1].trim() : "";

    // Heading should usually be surrounded by blank lines
    if(previous==="") return true;

    if(next==="") return true;

    // Or followed by bullet list

    if(isBullet(next)) return true;

    // Or followed by numbered list

    if(/^\d+[\.\)]/.test(next)) return true;

    return false;

}

// =======================================================
// PART 2
// Section Extraction Engine
// =======================================================


// ---------------- Detect Heading Level ----------------

function getHeadingLevel(line){

    // Markdown headings
    const md = line.match(/^(#{1,6})\s+/);

    if(md){
        return md[1].length;
    }

    // Number headings
    const num = line.match(/^(\d+(?:\.\d+)*)/);

    if(num){
        return num[1].split(".").length;
    }

    return 1;

}



// ---------------- Clean Heading ----------------

function cleanHeading(line){

    return line
        .replace(/^#{1,6}\s+/,"")
        .replace(/^\d+(\.\d+)*[\.\)]\s+/,"")
        .trim();

}



// =======================================================
// Extract Logical Sections
// =======================================================

function extractSections(text){

    const lines = text.split(/\r?\n/);

    const sections = [];

    let currentTitle = "Document";

    let currentLevel = 1;

    let currentContent = [];



    function saveSection(){

        const body = currentContent.join("\n").trim();

        if(body.length===0){

            currentContent=[];

            return;

        }

        sections.push({

            title: currentTitle,

            level: currentLevel,

            text: body

        });

        currentContent=[];

    }



    for(let i=0;i<lines.length;i++){

        const raw = lines[i];

        const line = raw.trim();



        // Preserve paragraph spacing

        if(isBlank(line)){

            currentContent.push("");

            continue;

        }



        // Detect new heading

        if(isHeading(lines,i)){

            saveSection();

            currentTitle = cleanHeading(line);

            currentLevel = getHeadingLevel(line);

            continue;

        }



        currentContent.push(raw);

    }



    saveSection();



    // If entire document has no headings,
    // return one section containing whole document.

    if(sections.length===0){

        sections.push({

            title:"Document",

            level:1,

            text:text.trim()

        });

    }



    return sections;

}


// =======================================================
// PART 3
// Smart Section Chunking Engine
// =======================================================


// =======================================================
// Find Best Breaking Position
// Priority:
// Paragraph -> Sentence -> Bullet -> New Line -> Space
// =======================================================

function findBestBreak(text, idealEnd){

    if(idealEnd >= text.length){
        return text.length;
    }

    const searchStart = Math.max(
        0,
        idealEnd - CONFIG.SEARCH_WINDOW
    );

    const searchText = text.substring(
        searchStart,
        idealEnd
    );



    // ------------------------------------
    // Paragraph
    // ------------------------------------

    let index = searchText.lastIndexOf("\n\n");

    if(index !== -1){

        return searchStart + index + 2;

    }



    // ------------------------------------
    // Sentence
    // ------------------------------------

    const sentenceRegex = /[.!?]["')\]]?\s/g;

    let match;

    let sentenceBreak = -1;

    while((match = sentenceRegex.exec(searchText)) !== null){

        sentenceBreak = match.index + 1;

    }

    if(sentenceBreak !== -1){

        return searchStart + sentenceBreak;

    }



    // ------------------------------------
    // Bullet
    // ------------------------------------

    const bulletRegex = /\n\s*[-*•]\s/g;

    let bulletBreak = -1;

    while((match = bulletRegex.exec(searchText)) !== null){

        bulletBreak = match.index + 1;

    }

    if(bulletBreak !== -1){

        return searchStart + bulletBreak;

    }



    // ------------------------------------
    // Line Break
    // ------------------------------------

    index = searchText.lastIndexOf("\n");

    if(index !== -1){

        return searchStart + index + 1;

    }



    // ------------------------------------
    // Word Boundary
    // ------------------------------------

    index = searchText.lastIndexOf(" ");

    if(index !== -1){

        return searchStart + index + 1;

    }



    return idealEnd;

}



// =======================================================
// Adjust Start
// Never begin in the middle of a word
// =======================================================

function adjustStart(text,start){

    if(start<=0){

        return 0;

    }



    while(

        start<text.length &&

        !/\s/.test(text[start])

    ){

        start++;

    }



    while(

        start<text.length &&

        /\s/.test(text[start])

    ){

        start++;

    }



    return start;

}



// =======================================================
// Chunk One Section
// =======================================================

function chunkSection(section){

    const chunks=[];

    const text=section.text;



    // --------------------------
    // Small section
    // --------------------------

    if(text.length<=CONFIG.CHUNK_SIZE){

        chunks.push({

            section_title:section.title,

            section_level:section.level,

            chunk_text:text,

            chunk_start:0,

            chunk_end:text.length,

            contains_heading:true

        });

        return chunks;

    }



    // --------------------------
    // Large section
    // --------------------------

    let start=0;



    while(start<text.length){

        const idealEnd=Math.min(

            start+CONFIG.CHUNK_SIZE,

            text.length

        );



        let end=findBestBreak(

            text,

            idealEnd

        );



        // Safety

        if(end<=start){

            end=idealEnd;

        }



        let chunk=text

            .substring(start,end)

            .trim();



        if(

            chunk.length>=CONFIG.MIN_CHUNK_SIZE

        ){

            chunks.push({

                section_title:section.title,

                section_level:section.level,

                chunk_text:chunk,

                chunk_start:start,

                chunk_end:end,

                contains_heading:start===0

            });

        }



        if(end>=text.length){

            break;

        }



        start=adjustStart(

            text,

            end-CONFIG.OVERLAP

        );

    }



    return chunks;

}



// =======================================================
// Chunk Entire Document
// =======================================================

function buildChunks(text){

    const sections=extractSections(text);

    const chunks=[];



    for(const section of sections){

        chunks.push(

            ...chunkSection(section)

        );

    }



    return chunks;

}

// =======================================================
// PART 4
// Main Execution Engine
// =======================================================

const output = [];

for (const item of items) {

    const text = item.json.normalized_text || "";

    if (!text.trim()) {
        continue;
    }

    // ------------------------------------------
    // Build intelligent chunks
    // ------------------------------------------

    const chunks = buildChunks(text);

    const totalChunks = chunks.length;

    chunks.forEach((chunk, index) => {

        // ------------------------------------------
        // Add heading to chunk for better retrieval
        // ------------------------------------------

        let finalChunk = chunk.chunk_text;

        if (
            chunk.section_title &&
            !finalChunk.startsWith(chunk.section_title)
        ) {

            finalChunk =
                chunk.section_title +
                "\n\n" +
                finalChunk;

        }

        output.push({

            json: {

                // ==================================
                // Original document metadata
                // ==================================

                ...item.json,

                // ==================================
                // Chunk Identity
                // ==================================

                chunk_uuid: generateUUID(),

                chunk_id:
                    `${item.json.document_uuid}_${index + 1}`,

                chunk_index: index,

                total_chunks: totalChunks,

                // ==================================
                // Section Information
                // ==================================

                section_title: chunk.section_title,

                section_level: chunk.section_level,

                contains_heading: chunk.contains_heading,

                // ==================================
                // Chunk Position
                // ==================================

                chunk_start: chunk.chunk_start,

                chunk_end: chunk.chunk_end,

                // ==================================
                // Chunk Content
                // ==================================

                chunk_text: finalChunk,

                // ==================================
                // Chunk Statistics
                // ==================================

                chunk_characters: finalChunk.length,

                chunk_words:
                    finalChunk
                        .split(/\s+/)
                        .filter(Boolean)
                        .length,

                chunk_lines:
                    finalChunk
                        .split("\n")
                        .length,

                // ==================================
                // Useful Retrieval Metadata
                // ==================================

                chunk_hash:
                    item.json.hash,

                document_hash:
                    item.json.hash,

                parser_type:
                    item.json.parser_type,

                extraction_method:
                    item.json.extraction_method,

                department:
                    item.json.department,

                category:
                    item.json.category,

                source:
                    item.json.source

            },

            binary: item.binary

        });

    });

}

return output;

